import assert from 'node:assert/strict';
import { createController } from './src/controller.js';

let resolveFirst;
const calls = [];
const auditEntries = [];
const renders = [];
const service = { commit(snapshot) {
  calls.push(snapshot);
  return new Promise(resolve => { resolveFirst = resolve; });
} };
const controller = createController({
  service,
  audit: { record(entry) { auditEntries.push(entry); } },
  render(view) { renders.push(view); },
});
controller.open('doc-1', 'actor-1');
controller.edit('first');
const result = controller.submit();
assert.equal(typeof result.then, 'function');
controller.edit('later');
controller.close();
controller.open('doc-1', 'actor-2');
resolveFirst({ revision: 'r1' });
assert.deepEqual(await result, { revision: 'r1' });
assert.deepEqual(calls, [{ doc: 'doc-1', actor: 'actor-1', text: 'first' }]);
assert.deepEqual(auditEntries, [{ doc: 'doc-1', actor: 'actor-1', text: 'first', revision: 'r1' }]);
assert.deepEqual(renders, []);

const rejection = new Error('offline');
service.commit = () => Promise.reject(rejection);
const failed = controller.submit();
await assert.rejects(failed, error => error === rejection);
assert.deepEqual(renders, [{ status: 'error', doc: 'doc-1' }]);
assert.equal(auditEntries.length, 1);

let finishOld;
service.commit = () => new Promise(resolve => { finishOld = resolve; });
const old = controller.submit();
service.commit = () => Promise.resolve({ revision: 'r2' });
const latest = controller.submit();
finishOld({ revision: 'r-old' });
await old;
await latest;
assert.deepEqual(renders, [
  { status: 'error', doc: 'doc-1' },
  { status: 'saved', doc: 'doc-1' },
]);
assert.equal(auditEntries.length, 3);
